import os
import sys
import json
import logging
if sys.version_info[0] >= 3 and sys.version_info[1] >= 5:
    from jsonschema import validate
from functools import wraps


class CommandResult(object):
    def __init__(self, origial, dictionary=None, bean=None):
        self._origial = origial
        self._dic = dictionary
        self._bean = bean

    @property
    def origial(self):
        return self._origial

    @property
    def dictionary(self):
        return self._dic

    @property
    def bean(self):
        return self._bean


class JsonCommand(object):
    def __init__(self, executor):
        self._executor = executor

    def _create_request_bean_dict(self, *args, **kwargs):
        raise NotImplementedError()

    def _create_response_bean(self, *args, **kwargs):
        raise NotImplementedError()

    def _validate_json(self, json_dict, schema_dict=None):
        if schema_dict:
            if sys.version_info[0] >= 3 and sys.version_info[1] >= 5:
                validate(instance=json_dict, schema=schema_dict)
            else:
                logging.debug("json validation is not supported in python <3.5")

    def _validate_request_json(self, json_dict, schema_dict=None):
        self._validate_json(json_dict, schema_dict=schema_dict)

    def _validate_response_json(self, json_dict, schema_dict=None):
        self._validate_json(json_dict, schema_dict=schema_dict)

    def execute(self, *args, **params):
        until_timeout = None
        if 'until_timeout' in params:
            until_timeout = params['until_timeout']
            params.pop('until_timeout')

        request_bean_dict = self._create_request_bean_dict(*args, **params)
        self._validate_request_json(request_bean_dict)

        json_request_msg = json.dumps(request_bean_dict)
        logging.info("request message is: {}".format(json_request_msg))
        json_response_msg = self._executor.execute_until(msg=json_request_msg, timeout=until_timeout)
        logging.info("response message is: {}".format(json_response_msg))
        json_dic = json.loads(json_response_msg)
        self._validate_response_json(json_dic)

        return CommandResult(origial=json_response_msg,
                             dictionary=json_dic,
                             bean=self._create_response_bean(**json_dic))

    def __call__(self, *args, **kwargs):
        return self.execute(*args, **kwargs)


def normalize_relative_file_path(relative_path):
    return relative_path \
        if relative_path.startswith(os.path.sep) or relative_path.startswith('/') \
        else os.path.sep + relative_path


def load_json_schema(schema):
    current_dir = os.path.dirname(os.path.abspath(__file__))
    if schema:
        request_schema_path = current_dir + normalize_relative_file_path(schema)
        with open(request_schema_path, 'r') as f:
            content = f.read()
            return json.loads(content)


def json_validate(request_schema=None, response_schema=None):

    def wrapper(cls):
        if not issubclass(cls, JsonCommand):
            raise Exception("json_validate only can decorate subclass of JsonCommand")

        def validate_request_json_decorator(func):
            @wraps(func)
            def decorated(self, json_dict):
                schema_dict = load_json_schema(request_schema)
                func(self, json_dict, schema_dict=schema_dict)
            return decorated

        def validate_response_json_decorator(func):
            @wraps(func)
            def decorated(self, json_dict):
                schema_dict = load_json_schema(response_schema)
                func(self, json_dict, schema_dict=schema_dict)
            return decorated

        setattr(cls, cls._validate_request_json.__name__, validate_request_json_decorator(cls._validate_request_json))
        setattr(cls, cls._validate_response_json.__name__, validate_response_json_decorator(cls._validate_response_json))

        return cls

    return wrapper


def covert_namedtuple_to_dict(content):
    content_dict = content._asdict()
    for key, value in content_dict.items():
        if hasattr(value, '_asdict'):
            content_dict[key] = covert_namedtuple_to_dict(value)
    return content_dict


class NamedTupleBeanJsonCommand(JsonCommand):

    def _create_request_bean(self, *args, **kwargs):
        raise NotImplementedError()

    def _create_request_bean_dict(self, *args, **kwargs):
        bean = self._create_request_bean(*args, **kwargs)
        return covert_namedtuple_to_dict(bean)
